import { _decorator, Button, Color, Component, director, Label, Node, sp, Sprite, tween, Tween, UIOpacity, Vec3 } from "cc";
import AppAudio from "../audio/AppAudio";
import { EFFECTSMAP } from '../audio/AudioConfig';
import StoreManager from "../store/StoreManager";
import { GameViewAdapter } from "./GameViewAdapter";
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from "../events/GameRuntimeEventBus";

const { ccclass, property } = _decorator;

const THRESHOLDS: { min: number; key: string }[] = [
    { min: 200, key: "epic" },
    { min: 100, key: "super" },
    { min: 50, key: "mega" },
    { min: 25, key: "big" },
    { min: 10, key: "win" },
];

const WIN_LOOP_MAP: Record<string, string> = {
    big: EFFECTSMAP.BIGWIN_LOOP,
    super: EFFECTSMAP.SUPERWIN_LOOP,
    mega: EFFECTSMAP.HUGEWIN_LOOP,
    epic: EFFECTSMAP.GIGANTICWIN_LOOP,
};

const ESCALATE: string[] = ["big", "mega", "super", "epic"];
const ESCALATE_DWELL = 2.0;

@ccclass("1002/gs002/WinAnimationView")
export class WinAnimationView extends Component {

    @property(sp.Skeleton)
    winSpine: sp.Skeleton = null!;

    @property(Label)
    winLabel: Label = null!;

    @property(Button)
    dismissBtn: Button = null!;

    private resolveClose: (() => void) | null = null;
    private scoreTimer: number = 0;
    private dismissTimer: number = 0;
    private dismissed: boolean = false;
    private currentKey: string = "";
    private currentLoopPath: string = "";
    private escalateTimers: number[] = [];
    private bgmFadeObj = { vol: 1 };
    public onDismissing: (() => void) | null = null;

    public dismissExternal(): void {
        this.onDismiss();
    }

    private _disposeReaction: (() => void) | null = null;
    private _disposeOrientation: (() => void) | null = null;
    private adapterDefaults = new Map<Node, { position: Vec3; scale: Vec3 }>();

    protected override onLoad(): void {
        this.dismissBtn.node.on(Button.EventType.CLICK, this.onDismiss, this);
        this.applyAdapterOverride();
        this._disposeOrientation = gameRuntimeEventBus.on(GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, () => {
            this.applyAdapterOverride();
        });
        const gameStore = StoreManager.getInstance().getGameStore();
        // mobx 移除計劃：SlotGameStore.winAnimationData 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this._disposeReaction = gameRuntimeEventBus.on(GAME_EVENT_TYPE.WIN_ANIMATION_DATA_CHANGED, (e) => {
            if (e.data) this.show(e.data.totalWin, e.data.bet).then(() => gameStore.completeWinAnimation());
        });
        const data = gameStore.winAnimationData;
        if (data) this.show(data.totalWin, data.bet).then(() => gameStore.completeWinAnimation());
    }

    private applyAdapterOverride(): void {
        for (const [contentNode, defaults] of this.adapterDefaults) {
            if (!contentNode.isValid) continue;
            contentNode.setPosition(defaults.position);
            contentNode.setScale(defaults.scale);
        }
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return;
        const adapters = scene.getComponentsInChildren(GameViewAdapter);
        const adapter = adapters.find(a => a.node.name === adapterName);
        if (!adapter || !adapter.winAnimationContentNodeName) return;
        const contentNode = this.node.getChildByName(adapter.winAnimationContentNodeName);
        if (!contentNode) {
            console.warn(`[WinAnim] content node '${adapter.winAnimationContentNodeName}' not found`);
            return;
        }
        let defaults = this.adapterDefaults.get(contentNode);
        if (!defaults) {
            defaults = { position: contentNode.position.clone(), scale: contentNode.scale.clone() };
            this.adapterDefaults.set(contentNode, defaults);
        }
        contentNode.setPosition(defaults.position);
        contentNode.setScale(defaults.scale);
        const lp = adapter.winAnimationContentLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) contentNode.setPosition(lp);
        const sc = adapter.winAnimationContentScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) contentNode.setScale(sc);
    }

    protected override onDestroy(): void {
        this._disposeReaction?.();
        this._disposeReaction = null;
        this._disposeOrientation?.();
        this._disposeOrientation = null;
        if (this.dismissTimer) { clearTimeout(this.dismissTimer); this.dismissTimer = 0; }
        if (this.scoreTimer) { clearTimeout(this.scoreTimer); this.scoreTimer = 0; }
        this.clearEscalateTimers();
        Tween.stopAllByTarget(this.node);
    }

    static getWinKey(totalWin: number, bet: number): string | null {
        const multiplier = bet > 0 ? totalWin / bet : 0;
        for (const t of THRESHOLDS) {
            if (multiplier >= t.min) return t.key;
        }
        return null;
    }

    show(totalWin: number, bet: number, forceKey?: string): Promise<void> {
        const key = forceKey ?? WinAnimationView.getWinKey(totalWin, bet);
        if (!key) return Promise.resolve();

        this.applyAdapterOverride();

        return new Promise(resolve => {
            this.resolveClose = resolve;
            this.dismissed = false;
            this.scoreFinished = false;
            this.waitingDismiss = false;
            this.currentKey = "";
            this.node.active = true;

            AppAudio.getInstance().playEffect(EFFECTSMAP.WIN_START);
            this.fadeBgm(0, 0.5);
            this.fadeBlackBg(153, 0.333);

            this.winLabel.string = "";
            this.winLabel.node.active = true;
            this.winSpine.node.active = true;

            const label = this.winLabel;
            const isEscalate = key !== "win" && key !== "total";
            const targetIdx = ESCALATE.indexOf(key);
            this.playTier(isEscalate ? "big" : key);
            this.playLabelBirth(label);
            setTimeout(() => { if (this.winSpine?.node?.isValid) this.playLabelIdle(label); }, 500);

            const loopPath = WIN_LOOP_MAP[key];
            if (loopPath) {
                this.currentLoopPath = loopPath;
                setTimeout(() => {
                    if (this.currentLoopPath === loopPath) {
                        AppAudio.getInstance().playLoopEffect(loopPath);
                    }
                }, 500);
            }
            const multiplier = bet > 0 ? totalWin / bet : 0;
            let scoreDuration: number;
            this.clearEscalateTimers();
            if (key === "total") {
                scoreDuration = 0;
            } else if (isEscalate) {
                scoreDuration = (targetIdx + 1) * ESCALATE_DWELL;
                for (let i = 1; i <= targetIdx; i++) {
                    const tk = ESCALATE[i];
                    this.escalateTimers.push(setTimeout(() => this.playTier(tk), i * ESCALATE_DWELL * 1000) as unknown as number);
                }
            } else {
                scoreDuration = Math.min(multiplier / 2, 15);
            }
            this.runScore(totalWin, scoreDuration, label).then(() => {
                if (this.scoreFinished) return;
                this.scoreFinished = true;
                this.stopLoopAndPlayEnd();
                this.startWaitingDismiss();
            });
        });
    }

    dismiss(): void {
        this.onDismiss();
    }

    private scoreFinished: boolean = false;
    private waitingDismiss: boolean = false;

    private _notifying: boolean = false;
    private onDismiss(): void {
        if (this.dismissed) return;
        if (!this._notifying) {
            this._notifying = true;
            try { this.onDismissing?.(); } finally { this._notifying = false; }
        }

        if (!this.scoreFinished) {
            this.scoreFinished = true;
            this.clearEscalateTimers();
            this.stopScore();
            this.stopLoopAndPlayEnd();
            this.startWaitingDismiss();
            return;
        }

        if (this.waitingDismiss) {
            this.waitingDismiss = false;
            if (this.dismissTimer) {
                clearTimeout(this.dismissTimer);
                this.dismissTimer = 0;
            }
            this.playOff();
            return;
        }

        this.playOff();
    }

    private startWaitingDismiss(): void {
        this.waitingDismiss = true;
        if (this.dismissTimer) clearTimeout(this.dismissTimer);
        this.dismissTimer = setTimeout(() => {
            this.dismissTimer = 0;
            this.waitingDismiss = false;
            this.onDismiss();
        }, 2000) as unknown as number;
    }

    private fadeBlackBg(target: number, duration: number): void {
        const node = this.dismissBtn?.node;
        if (!node) return;
        const sprite = node.getComponent(Sprite);
        if (sprite) sprite.color = new Color(0, 0, 0, 255);
        const uo = node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
        if (target > 0) uo.opacity = 0;
        Tween.stopAllByTarget(uo);
        tween(uo).to(duration, { opacity: target }).start();
    }

    private playOff(): void {
        if (this.dismissed) return;
        this.dismissed = true;
        this.fadeBlackBg(0, 0.333);
        if (this.dismissTimer) {
            clearTimeout(this.dismissTimer);
            this.dismissTimer = 0;
        }

        if (this.winLabel.node.active) this.playLabelOff(this.winLabel);

        if (!this.winSpine.node.active || !this.currentKey) { this.close(); return; }

        const safetyTimer = setTimeout(() => this.close(), 1000);
        try {
            this.winSpine.setAnimation(0, `${this.currentKey}_end`, false);
            this.winSpine.setCompleteListener(() => {
                clearTimeout(safetyTimer);
                this.winSpine.setCompleteListener(null!);
                this.close();
            });
        } catch (e) {
            clearTimeout(safetyTimer);
            this.close();
        }
    }

    private close(): void {
        this.stopLoopAndPlayEnd();
        this.fadeBgm(1, 0.5, () => {
            if (this.node?.isValid) this.node.active = false;
            const resolve = this.resolveClose;
            this.resolveClose = null;
            resolve?.();
        });
    }

    private stopLoopAndPlayEnd(): void {
        if (this.currentLoopPath) {
            AppAudio.getInstance().stopLoopEffect(this.currentLoopPath, EFFECTSMAP.WIN_END);
            this.currentLoopPath = "";
        }
    }

    private clearEscalateTimers(): void {
        for (const t of this.escalateTimers) clearTimeout(t);
        this.escalateTimers = [];
    }

    private playTier(key: string): void {
        this.currentKey = key;
        try {
            this.winSpine.setAnimation(0, `${key}_begin`, false);
            this.winSpine.setCompleteListener(() => {
                this.winSpine.setCompleteListener(null!);
                if (this.currentKey === key && this.winSpine.node?.isValid) {
                    this.winSpine.setAnimation(0, `${key}_loop`, true);
                }
            });
        } catch (e) { }
    }

    private scoreTargetWin: number = 0;
    private scoreLabel: Label | null = null;

    private runScore(totalWin: number, duration: number, label: Label, onTick?: (cur: number) => void): Promise<void> {
        this.stopScore();
        this.scoreTargetWin = totalWin;
        this.scoreLabel = label;
        const steps = Math.ceil(duration / 0.016);
        let step = 0;
        return new Promise<void>(resolve => {
            const tick = () => {
                step++;
                const ratio = step >= steps ? 1 : step / steps;
                const cur = totalWin * ratio;
                label.string = StoreManager.getInstance().getGameStore().formatAmount(cur);
                onTick?.(cur);
                if (step < steps) {
                    this.scoreTimer = setTimeout(tick, 16) as unknown as number;
                } else {
                    resolve();
                }
            };
            tick();
        });
    }

    private stopScore(): void {
        if (this.scoreTimer) {
            clearTimeout(this.scoreTimer);
            this.scoreTimer = 0;
            if (this.scoreLabel) {
                this.scoreLabel.string = StoreManager.getInstance().getGameStore().formatAmount(this.scoreTargetWin);
            }
        }
    }

    private playLabelBirth(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        node.setScale(0.3, 0.3, 1);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 0;
        tween(uiOpacity).to(0.333, { opacity: 255 }).start();

        tween(node)
            .to(0.333, { scale: new Vec3(1.15, 1.15, 1) }, { easing: 'backOut' })
            .to(0.167, { scale: new Vec3(1, 1, 1) })
            .start();
    }

    private playLabelIdle(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        tween(node)
            .to(0.233, { scale: new Vec3(0.95, 0.95, 1) })
            .to(0.5, { scale: new Vec3(1.05, 1.05, 1) })
            .to(0.267, { scale: new Vec3(1, 1, 1) })
            .union()
            .repeatForever()
            .start();
    }

    private playLabelOff(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
        tween(uiOpacity).delay(0.167).to(0.333, { opacity: 0 }).start();

        tween(node)
            .to(0.167, { scale: new Vec3(0.9, 0.9, 1) })
            .to(0.333, { scale: new Vec3(2, 2, 1) })
            .start();
    }

    private fadeBgm(target: number, duration: number, onComplete?: () => void): void {
        const audio = AppAudio.getInstance();
        Tween.stopAllByTarget(this.bgmFadeObj);
        this.bgmFadeObj.vol = target === 0 ? 1 : 0;
        tween(this.bgmFadeObj)
            .to(duration, { vol: target }, {
                onUpdate: () => {
                    // 1002 目前沒有背景音樂素材，MUSICMAP 也不是從 SGEngine/Common/SOUNDMAP
                    // export 出來的東西（該檔案只有 EFFECTSMAP），原本這行執行期一定是
                    // undefined.BGM，直接崩潰。先註解掉，等 1002 補齊音樂素材、建好
                    // 專屬的 AudioConfig.ts（比照 1001 的做法）後再打開。
                    // audio.setLoopEffectVolume(MUSICMAP.BGM, this.bgmFadeObj.vol);
                }
            })
            .call(() => onComplete?.())
            .start();
    }
}
