import { _decorator, Component, Label, Node, Sprite, UIOpacity, UITransform, sp } from 'cc';
import StoreManager from '../../store/StoreManager';

const { ccclass, property } = _decorator;

@ccclass('1002/gs002/NgSymbol')
export class NgSymbol extends Component {
    @property(Label)
    coinLabel: Label = null!;

    private symbolWin: sp.Skeleton = null!;
    private symbolH: sp.Skeleton = null!;
    private symbolL: sp.Skeleton = null!;
    private symbolUp: sp.Skeleton = null!;
    private symbolM: sp.Skeleton = null!;
    private symbolMFx: sp.Skeleton = null!;
    private symbolScatter: sp.Skeleton = null!;
    private symbolFrame: sp.Skeleton = null!;
    private spriteFrameNode: Node = null!;

    /** DebugPanel「Symbol 縮放」用的整體縮放倍率，套在 visual 容器上，預設 1(1002 美術尺寸本來就對，不需要額外縮放) */
    private scaleMultiplier: number = 1;

    private visual: Node = null!;

    protected override onLoad(): void {
        const v = this.buildVisualWrapper();
        this.symbolH = v.getChildByName('symbol_h')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolH) this.symbolH.node.active = false;

        this.symbolWin = v.getChildByName('symbol_win')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolWin) this.symbolWin.node.active = false;

        this.symbolL = v.getChildByName('symbol_l')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolL) this.symbolL.node.active = false;

        this.symbolUp = v.getChildByName('symbol_up')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolUp) this.symbolUp.node.active = false;

        this.spriteFrameNode = v.getChildByName('spriteFrame') ?? null!;

        // symbol_m = 倍率球動畫本體（begin/mul/collect）；預設關閉，只在倍率球 cell 開
        const mNode = v.getChildByName('symbol_m');
        this.symbolM = mNode?.getComponent(sp.Skeleton) ?? null!;

        // 數字 Label 掛在 symbol_m 底下，用顯式路徑抓（getChildByName 對 inactive 也有效）
        if (!this.coinLabel) this.coinLabel = mNode?.getChildByName('Label')?.getComponent(Label) ?? null!;
        if (this.coinLabel) this.coinLabel.node.active = false;
        if (this.symbolM) {
            try {
                this.symbolM.animation = '';
            } catch (e) {} // 清掉 prefab 預設自動播動畫，否則一 active 就自動 loop begin（進場/idle 全閃）
            this.symbolM.node.active = false;
        }

        // symbol_m_fx = 升級倍數特效（anubis/horus），疊在 symbol_m 之上蓋住數字；預設關
        const fxNode = v.getChildByName('symbol_m_fx');
        this.symbolMFx = fxNode?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolMFx) {
            try {
                this.symbolMFx.animation = '';
            } catch (e) {}
            this.symbolMFx.node.active = false;
        }

        this.symbolScatter = v.getChildByName('symbol_scatter')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolScatter) {
            try {
                this.symbolScatter.animation = '';
            } catch (e) {}
            this.symbolScatter.node.active = false;
        }

        this.symbolFrame = v.getChildByName('symbol_frame')?.getComponent(sp.Skeleton) ?? null!;
        if (this.symbolFrame) {
            try {
                this.symbolFrame.animation = '';
            } catch (e) {}
            this.symbolFrame.node.active = false;
        }
    }

    private buildVisualWrapper(): Node {
        const visual = new Node('visual');
        const rootUI = this.node.getComponent(UITransform);
        const visualUI = visual.addComponent(UITransform);
        if (rootUI) visualUI.setContentSize(rootUI.contentSize);
        const children = [...this.node.children];
        this.node.addChild(visual);
        for (const c of children) c.setParent(visual);
        this.visual = visual;
        this.applyVisualScale();
        return visual;
    }

    /** DebugPanel「Symbol 縮放」呼叫，即時套用不記錄 */
    setScaleMultiplier(scale: number): void {
        this.scaleMultiplier = scale;
        this.applyVisualScale();
    }

    private applyVisualScale(): void {
        this.visual?.setScale(this.scaleMultiplier, this.scaleMultiplier, 1);
    }

    showScatter(): void {
        if (!this.symbolScatter) return;
        this.symbolScatter.node.active = true;
        this.symbolScatter.timeScale = 1;
        try {
            this.symbolScatter.setAnimation(0, 'idle', true);
        } catch (e) {}
    }

    playScatterWin(): void {
        if (!this.symbolScatter) return;
        this.symbolScatter.node.active = true;
        this.symbolScatter.timeScale = 1;
        try {
            this.symbolScatter.setAnimation(0, 'win', true);
        } catch (e) {}
    }

    hideScatter(): void {
        if (this.symbolScatter) this.symbolScatter.node.active = false;
    }

    hasEliminateFx(): boolean {
        return !!this.symbolFrame;
    }

    /** 消除爆破：播 symbol_frame，美術表規格＝動畫第 133ms 才關閉 symbol；播完整格轉透明、符號圖還原 active 供補格重用 */
    playEliminate(timeScale = 1): Promise<void> {
        if (!this.symbolFrame) return Promise.resolve();
        const hideSymbol = () => {
            if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = false;
        };
        this.scheduleOnce(hideSymbol, 0.133 / timeScale);
        return this.playSpineOnce(this.symbolFrame, 'animation', 1.2, timeScale).then(() => {
            this.unschedule(hideSymbol);
            const op = this.getComponent(UIOpacity);
            if (op) op.opacity = 0;
            if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = true;
        });
    }

    /** 倍率球升級演出（企劃 §20/§17）：symbol_m 播一次 mul，到 200ms 切新倍數（換 tier skin + 數字），
     *  同時 symbol_m_fx 疊在球上播一次。 */
    playMul(side: number, newTier: number, newValue: number): Promise<void> {
        return new Promise<void>((resolve) => {
            if (this.symbolMFx) {
                this.symbolMFx.node.active = true;
                try {
                    this.symbolMFx.setAnimation(0, 'animation', false);
                } catch (e) {}
                this.symbolMFx.setCompleteListener((e) => {
                    if (e.trackIndex !== 0) return;
                    this.symbolMFx.setCompleteListener(null);
                    if (this.symbolMFx.node?.isValid) this.symbolMFx.node.active = false;
                });
                this.scheduleOnce(() => {
                    if (this.symbolMFx?.node?.isValid) this.symbolMFx.node.active = false;
                }, 1.2);
            }
            if (!this.symbolM) {
                resolve();
                return;
            }
            this.symbolM.node.active = true;
            try {
                this.symbolM.setAnimation(0, 'mul', false);
            } catch (e) {}
            // mul 播到 200ms 才切換成新倍數（換顏色階 skin + 數字）
            this.scheduleOnce(() => {
                try {
                    this.symbolM.setSkin(`m${side}_${newTier}`);
                } catch (e) {}
                if (this.coinLabel) this.coinLabel.string = `${newValue}x`;
            }, 0.2);
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                this.symbolM.setCompleteListener(null);
                resolve();
            };
            this.symbolM.setCompleteListener((e) => {
                if (e.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, 1.2);
        });
    }

    /** m 系列倍數符號出現時疊播 symbol_up 閃電光效。 */
    playUp(frameName: string): Promise<void> {
        return new Promise<void>((resolve) => {
            // 企劃 §19：symbol_m 的 begin「與 symbol_up 同時播放一次」（角色落雷把球打進盤面）。
            // 自包：自己 activate + 解析 skin + 藏靜態圖 + 播 begin（setSymbolDisplay 已不啟動 symbol_m）。
            const mm = frameName.match(/^symbol_m(\d)_(\d)/);
            if (mm && this.symbolM) {
                this.symbolM.node.active = true;
                try {
                    this.symbolM.setSkin(`m${mm[1]}_${mm[2]}`);
                } catch (e) {}
                try {
                    this.symbolM.setAnimation(0, 'begin', false);
                } catch (e) {}
                const spr = this.spriteFrameNode?.getComponent(Sprite);
                if (spr) spr.enabled = false;
            }
            const sk = this.symbolUp;
            if (!sk) {
                resolve();
                return;
            }
            sk.node.active = true;
            sk.setAnimation(0, 'animation', false);
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                sk.setCompleteListener(null);
                if (sk.node?.isValid) sk.node.active = false;
                resolve();
            };
            sk.setCompleteListener((e) => {
                if (e.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, 1.1);
        });
    }

    /** timeScale 隨三段速的 winFx 時長縮放（同 playEliminate 的做法），1 = 原速 */
    playWin(frameName?: string, timeScale = 1): Promise<void> {
        const tasks: Promise<void>[] = [this.playSpineOnce(this.symbolWin, 'animation', 1.6, timeScale)];
        if (frameName && this.symbolL && frameName.startsWith('symbol_l')) {
            tasks.push(this.playSymbolAnimation(this.symbolL, frameName, timeScale));
        }
        if (frameName && this.symbolH && frameName.startsWith('symbol_h')) {
            tasks.push(this.playSymbolAnimation(this.symbolH, frameName, timeScale));
        }
        return Promise.all(tasks).then(() => undefined);
    }

    private playSymbolAnimation(sk: sp.Skeleton, anim: string, timeScale = 1): Promise<void> {
        return new Promise<void>((resolve) => {
            if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = false;
            sk.node.active = true;
            sk.timeScale = timeScale;
            const entry = sk.setAnimation(0, anim, false);
            const dur = ((entry?.animation?.duration ?? 1.5) + 0.2) / timeScale;
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                sk.setCompleteListener(null);
                if (sk.node?.isValid) sk.node.active = false;
                if (this.spriteFrameNode?.isValid) this.spriteFrameNode.active = true;
                resolve();
            };
            sk.setCompleteListener((e) => {
                if (e.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, dur);
        });
    }

    /** 播一次性 spine 動畫,播完隱藏節點。loop=false 時 Cocos complete 不一定觸發,用 timeout 保底 */
    private playSpineOnce(sk: sp.Skeleton, anim: string, fallback: number, timeScale = 1): Promise<void> {
        return new Promise<void>((resolve) => {
            if (!sk) {
                resolve();
                return;
            }
            sk.node.active = true;
            sk.timeScale = timeScale;
            sk.setAnimation(0, anim, false);
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                sk.setCompleteListener(null);
                if (sk.node?.isValid) sk.node.active = false;
                resolve();
            };
            sk.setCompleteListener((entry) => {
                if (entry.trackIndex === 0) finish();
            });
            this.scheduleOnce(finish, fallback / timeScale);
        });
    }

    /** 停輪後顯示金額 */
    show(amount: string): void {
        if (this.coinLabel) {
            this.coinLabel.string = StoreManager.getInstance().getGameStore().formatAmount(Number(amount));
            this.coinLabel.node.active = true;
        }
    }

    /** 倍率球常駐顯示倍率值（例：50X）。球升級換值時重呼叫即可；非倍率球用 hide() 清掉。 */
    showMultiplier(value: number): void {
        if (!this.coinLabel) return;
        this.coinLabel.string = `${value}x`;
        this.coinLabel.node.active = true;
    }

    /** 倍率球用 symbol_m spine 當動畫本體：首次出現播 begin，skin 依 side+tier(顏色階)。 */
    showMultiplierBall(side: number, tier: number): void {
        if (!this.symbolM) return;
        this.symbolM.node.active = true;
        try {
            this.symbolM.setSkin(`m${side}_${tier}`);
        } catch (e) {}
        const spr = this.spriteFrameNode?.getComponent(Sprite); // 藏靜態球，避免「靜態圖 + 動畫球」雙球疊影
        if (spr) spr.enabled = false;
        // begin 不在這裡播 —— 企劃：begin「與 symbol_up 同時播放」（落定打雷那一刻），見 playUp
    }

    hideMultiplierBall(): void {
        if (this.symbolM) this.symbolM.node.active = false;
        const spr = this.spriteFrameNode?.getComponent(Sprite); // 還原靜態圖（非倍率球要顯示）
        if (spr) spr.enabled = true;
    }

    /** 此格目前是否正以 symbol_m 動畫球顯示（倖存倍率球）。掉落時用來保留球+數字、不切回靜態圖。 */
    isMultiplierBallActive(): boolean {
        return !!this.symbolM && this.symbolM.node.active;
    }

    /** 倍率球被收集：播 symbol_m 的 collect 動畫（球發光/反應），跟 collect spine 的軌跡同步。 */
    playCollect(): void {
        if (!this.symbolM) return;
        this.symbolM.node.active = true;
        try {
            this.symbolM.setAnimation(0, 'collect', false);
        } catch (e) {}
    }

    hide(): void {
        if (this.coinLabel) this.coinLabel.node.active = false;
    }
}
