import { _decorator, Component, Label, Node, tween, Tween, Vec3 } from 'cc';

const { ccclass, property } = _decorator;

@ccclass('1002/gs002/FrameMultiplierComp')
export class FrameMultiplierComp extends Component {
    @property(Label)
    label: Label = null!;

    private _scaleTween: Tween<Node> | null = null;

    protected override onLoad(): void {
        if (!this.label) this.label = this.node.getChildByName('Label')?.getComponent(Label);
    }

    protected override onEnable(): void {
        this._startScaleTween();
    }

    protected override onDisable(): void {
        this._stopScaleTween();
    }

    private _startScaleTween(): void {
        if (!this.label) return;
        const node = this.label.node;
        this._stopScaleTween();
        this._scaleTween = tween(node)
            .to(0.1333, { scale: new Vec3(2, 2, 1) }, { easing: 'sineOut' })
            .to(0.1, { scale: new Vec3(0.9, 0.9, 1) }, { easing: 'sineInOut' })
            .to(0.1, { scale: new Vec3(1.2, 1.2, 1) }, { easing: 'sineInOut' })
            .to(0.1, { scale: new Vec3(0.95, 0.95, 1) }, { easing: 'sineInOut' })
            .to(0.5667, { scale: new Vec3(1, 1, 1) }, { easing: 'sineOut' })
            .union()
            .repeatForever()
            .start();
    }

    private _stopScaleTween(): void {
        if (this._scaleTween) {
            this._scaleTween.stop();
            this._scaleTween = null;
        }
        if (this.label) {
            this.label.node.setScale(new Vec3(1, 1, 1));
        }
    }
}
