import { _decorator, Component, director, Label, Node, Tween, tween, UIOpacity, Vec3 } from 'cc';
import { sp } from 'cc';
import AppAudio from "../audio/AppAudio";
import { EFFECTSMAP } from '../audio/AudioConfig';
import StoreManager from "../store/StoreManager";
import { GameViewAdapter } from "./GameViewAdapter";
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from "../events/GameRuntimeEventBus";

const { ccclass, property } = _decorator;

@ccclass('1002/gs002/BonusResultView')
export class BonusResultView extends Component {

    @property(Label)
    winAmountLabel: Label = null!;

    @property(sp.Skeleton)
    bgSpine: sp.Skeleton = null!;

    private resolveClick: (() => void) | null = null;
    private dismissTimer: number = 0;
    private dismissed: boolean = false;
    /** dismiss 的瞬間觸發（給 peer view 同步用） */
    public onDismissing: (() => void) | null = null;

    public dismissExternal(): void {
        this.dismiss();
    }

    private _disposeReaction: (() => void) | null = null;

    protected override onLoad(): void {
        this.node.on(Node.EventType.TOUCH_END, this.onTouchEnd, this);
        this.applyAdapterOverride();
        const gameStore = StoreManager.getInstance().getGameStore();
        // mobx 移除計劃：SlotGameStore.bonusResultData 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this._disposeReaction = gameRuntimeEventBus.on(GAME_EVENT_TYPE.BONUS_RESULT_DATA_CHANGED, (e) => {
            if (e.data) this.show(e.data.totalWin).then(() => gameStore.completeBonusResult());
        });
        const data = gameStore.bonusResultData;
        if (data) this.show(data.totalWin).then(() => gameStore.completeBonusResult());
    }

    private applyAdapterOverride(): void {
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return;
        const adapter = scene.getComponentsInChildren(GameViewAdapter).find(a => a.node.name === adapterName);
        if (!adapter) return;
        const lp = adapter.bonusResultBgSpineLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) this.bgSpine.node.setPosition(lp);
        const sc = adapter.bonusResultBgSpineScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) this.bgSpine.node.setScale(sc);
    }

    show(totalWin: number): Promise<void> {
        this.node.active = true;
        this.dismissed = false;
        this.winAmountLabel.string = StoreManager.getInstance().getGameStore().formatAmount(totalWin);
        AppAudio.getInstance().playEffect(EFFECTSMAP.BONUS_END);

        this.playLabelOpen(this.winAmountLabel);

        // 播 open → loop
        try {
            this.bgSpine.setAnimation(0, 'BGpopup_open', false);
            this.bgSpine.setCompleteListener(() => {
                this.bgSpine.setCompleteListener(null!);
                this.bgSpine.setAnimation(0, 'BGpopup_loop', true);
                this.playLabelIdle(this.winAmountLabel);
            });
        } catch (e) { }

        this.dismissTimer = setTimeout(() => this.dismiss(), 5000) as unknown as number;
        return new Promise<void>(resolve => {
            this.resolveClick = resolve;
        });
    }

    private _notifying: boolean = false;
    private dismiss(): void {
        if (this.dismissed) return;
        this.dismissed = true;
        if (!this._notifying) {
            this._notifying = true;
            try { this.onDismissing?.(); } finally { this._notifying = false; }
        }
        if (this.dismissTimer) {
            clearTimeout(this.dismissTimer);
            this.dismissTimer = 0;
        }

        this.playLabelClose(this.winAmountLabel);

        // 播 close 動畫後隱藏
        try {
            this.bgSpine.setAnimation(0, 'BGpopup_close', false);
            const safetyTimer = setTimeout(() => this.close(), 1000);
            this.bgSpine.setCompleteListener(() => {
                clearTimeout(safetyTimer);
                this.bgSpine.setCompleteListener(null!);
                this.close();
            });
        } catch (e) {
            this.close();
        }
    }

    /** open: delay 0.233s → 0→1.0(0.2s) + 淡入 */
    private playLabelOpen(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        node.setScale(0, 0, 1);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 0;
        tween(uiOpacity).delay(0.233).to(0.2, { opacity: 255 }).start();

        tween(node)
            .delay(0.233)
            .to(0.2, { scale: new Vec3(1, 1, 1) }, { easing: 'backOut' })
            .start();
    }

    /** idle: 1.0→1.1(0.467s)→1.0(0.533s) 呼吸循環 */
    private playLabelIdle(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);
        tween(node)
            .to(0.467, { scale: new Vec3(1.1, 1.1, 1) })
            .to(0.533, { scale: new Vec3(1, 1, 1) })
            .union()
            .repeatForever()
            .start();
    }

    /** close: 1→0.8(0.1s)→0(0.2s) + 淡出 */
    private playLabelClose(label: Label): void {
        const node = label.node;
        Tween.stopAllByTarget(node);

        const uiOpacity = node.getComponent(UIOpacity) || node.addComponent(UIOpacity);
        uiOpacity.opacity = 255;
        tween(uiOpacity).delay(0.1).to(0.2, { opacity: 0 }).start();

        tween(node)
            .to(0.1, { scale: new Vec3(0.8, 0.8, 1) })
            .to(0.2, { scale: new Vec3(0, 0, 1) })
            .start();
    }

    private close(): void {
        if (this.node?.isValid) this.node.active = false;
        this.resolveClick?.();
        this.resolveClick = null;
    }

    private onTouchEnd(): void {
        this.dismiss();
    }

    protected override onDestroy(): void {
        this._disposeReaction?.();
        this._disposeReaction = null;
        this.node.off(Node.EventType.TOUCH_END, this.onTouchEnd, this);
        if (this.dismissTimer) {
            clearTimeout(this.dismissTimer);
            this.dismissTimer = 0;
        }
    }
}
